from pathlib import Path
p=Path('/etc/grafana/grafana.ini'); s=p.read_text(); s=s.replace('[server]\n','[server]\nprotocol = socket\nsocket = /var/lib/grafana/proxy/grafana.sock\nrouter_logging = true\n',1); p.write_text(s)
p=Path('/etc/default/grafana-server'); p.write_text(p.read_text()+'\n# Allow the nginx group to connect to the protected local socket.\numask 0007\n')
PY
cat > /etc/nginx/conf.d/larkspur-grafana.conf <<'EOF'
map $http_upgrade $grafana_connection {
    default upgrade;
    '' close;
}
map $request_uri $grafana_bad_path {
    default 0;
    ~*^[^?]*(?:%25|%2e|%2f|%5c|\x5c|/\.{1,2}(?:/|\?|$)) 1;
}
upstream larkspur_grafana_backend {
    server unix:/var/lib/grafana/proxy/grafana.sock;
}
server {
    listen 3000 default_server;
    listen [::]:3000 default_server;
    server_name larkspurcycles.com;
    access_log /var/log/nginx/grafana-access.log;
    if ($grafana_bad_path) { return 400; }
    location / {
        proxy_pass http://larkspur_grafana_backend/;
        proxy_http_version 1.1;
        proxy_set_header Host $http_host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $remote_addr;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection $grafana_connection;
    }
}
EOF
